$root = dirname(__DIR__);
$cache = $root.'/bootstrap/cache';
if (! is_dir($cache)) {
    mkdir($cache, 0775, true);
}

$packages = base64_decode('');
$services = base64_decode('');

$ok1 = file_put_contents($cache.'/packages.php', $packages);
$ok2 = file_put_contents($cache.'/services.php', $services);
echo $ok1 ? "OK: packages.php\n" : "FAIL packages.php\n";
echo $ok2 ? "OK: services.php\n" : "FAIL services.php\n";

// Set all staff passwords to 12345678
$envPath = $root.'/.env';
function env_val($path, $key, $default = null)
{
    foreach (file($path, FILE_IGNORE_NEW_LINES) as $line) {
        $line = trim($line);
        if ($line === '' || str_starts_with($line, '#') || ! str_contains($line, '=')) {
            continue;
        }
        [$k, $v] = explode('=', $line, 2);
        if (trim($k) !== $key) {
            continue;
        }
        $v = trim($v);
        if ((str_starts_with($v, '"') && str_ends_with($v, '"')) || (str_starts_with($v, "'") && str_ends_with($v, "'"))) {
            $v = substr($v, 1, -1);
        }

        return $v;
    }

    return $default;
}

try {
    $pdo = new PDO(
        'mysql:host='.env_val($envPath, 'DB_HOST', 'localhost').';port='.env_val($envPath, 'DB_PORT', '3306').';dbname='.env_val($envPath, 'DB_DATABASE').';charset=utf8mb4',
        env_val($envPath, 'DB_USERNAME'),
        env_val($envPath, 'DB_PASSWORD', ''),
        [PDO::ATTR_ERRMODE => PDO::ERRMODE_EXCEPTION]
    );
    $hash = '$2y$12$byl1AvmT.3x4iGiwCJl9wumIC.XZIIFq/cviT18VJjZyxkAlvwyqa';
    $stmt = $pdo->prepare('UPDATE users SET password = ?, updated_at = NOW() WHERE email = ?');
    foreach (['admin@gmail.com', 'sales@tpi.com', 'telecaller@tpi.com'] as $email) {
        $stmt->execute([$hash, $email]);
        echo "OK: password 12345678 for $email\n";
    }
} catch (Throwable $e) {
    echo 'WARN: '.$e->getMessage()."\n";
}

echo "\nDONE — login with sales@tpi.com / 12345678\n";
